#!/usr/bin/env python3
"""Temporary LOOP model switching plus a curated OpenCodex model catalog.

Provider credentials remain exclusively in ``~/.opencodex/config.json``.
This manager changes model references and provider allowlists, never API keys.
"""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import time
import tomllib
from typing import Any


ROOT = Path(__file__).resolve().parents[1]
CODEX_HOME = Path.home() / ".codex"
OPENCODEX_HOME = Path.home() / ".opencodex"
WSL_ROOT = Path(r"\\wsl.localhost\Ubuntu\home\codexloop\codex-loop-s-f2")
PROFILE_TOOL = ROOT / "harness" / "model_profile.py"
PROFILE_CONFIG = ROOT / "config" / "model_profiles.toml"
ALLOWLIST_CONFIG = ROOT / "config" / "model_catalog_allowlist.toml"
MARKER = ROOT / "data" / "governor" / "temporary_model_route.json"
TEMPORARY_PROFILE = "grok-v4p"


class RouteManagerError(RuntimeError):
    pass


def atomic_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f"{path.name}.tmp.{os.getpid()}")
    try:
        with temporary.open("w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    except Exception:
        temporary.unlink(missing_ok=True)
        raise


def atomic_json(path: Path, value: Any) -> None:
    atomic_text(path, json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def load_toml(path: Path) -> dict[str, Any]:
    try:
        with path.open("rb") as handle:
            return tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise RouteManagerError(f"cannot read {path}: {exc}") from exc


def profile_state() -> dict[str, str]:
    document = load_toml(PROFILE_CONFIG)
    active = str(document.get("active_profile") or "")
    profile = (document.get("profiles") or {}).get(active)
    if not active or not isinstance(profile, dict):
        raise RouteManagerError("active model profile is missing")
    return {
        "profile": active,
        "execution_model": str(profile.get("execution_model") or ""),
        "execution_reasoning": str(profile.get("execution_reasoning") or ""),
        "review_model": str(profile.get("review_model") or ""),
        "review_reasoning": str(profile.get("review_reasoning") or ""),
    }


def run_profile(name: str) -> None:
    command = [
        sys.executable, str(PROFILE_TOOL), "set", name,
        "--root", str(ROOT),
        "--codex-home", str(CODEX_HOME),
        "--wsl-root", str(WSL_ROOT),
        "--json",
    ]
    result = subprocess.run(command, text=True, capture_output=True)
    if result.returncode != 0:
        detail = (result.stderr or result.stdout).strip()
        raise RouteManagerError(f"profile switch to {name!r} failed: {detail}")


def backup_runtime() -> Path:
    stamp = time.strftime("%Y%m%d-%H%M%S")
    destination = OPENCODEX_HOME / "backups" / f"model-route-manager-{stamp}"
    suffix = 0
    while destination.exists():
        suffix += 1
        destination = OPENCODEX_HOME / "backups" / f"model-route-manager-{stamp}-{suffix}"
    destination.mkdir(parents=True)
    sources = {
        OPENCODEX_HOME / "config.json": "opencodex-config.json",
        CODEX_HOME / "config.toml": "codex-config.toml",
        CODEX_HOME / "opencodex-catalog.json": "opencodex-catalog.json",
        PROFILE_CONFIG: "model_profiles.toml",
    }
    for source, name in sources.items():
        if source.is_file():
            shutil.copy2(source, destination / name)
    return destination


def allowlist() -> tuple[list[str], dict[str, list[str]], list[str]]:
    document = load_toml(ALLOWLIST_CONFIG)
    native = [str(item) for item in (document.get("native") or {}).get("visible", [])]
    providers = {
        str(name): [str(item) for item in values]
        for name, values in (document.get("providers") or {}).items()
        if isinstance(values, list)
    }
    fallbacks = [str(item) for item in (document.get("featured") or {}).get("fallbacks", [])]
    if not native or not providers:
        raise RouteManagerError("model catalog allowlist is empty")
    return native, providers, fallbacks


def routed_allowset(providers: dict[str, list[str]]) -> set[str]:
    return {f"{provider}/{model}" for provider, models in providers.items() for model in models}


def curated_featured(native: list[str], providers: dict[str, list[str]],
                     fallbacks: list[str]) -> list[str]:
    state = profile_state()
    permitted = set(native) | routed_allowset(providers)
    candidates = [state["execution_model"], state["review_model"], *fallbacks]
    result: list[str] = []
    for candidate in candidates:
        if candidate and candidate in permitted and candidate not in result:
            result.append(candidate)
        if len(result) == 5:
            break
    if state["execution_model"] not in result:
        raise RouteManagerError("active execution model is absent from the catalog allowlist")
    return result


def curate_opencodex() -> dict[str, Any]:
    config_path = OPENCODEX_HOME / "config.json"
    catalog_path = CODEX_HOME / "opencodex-catalog.json"
    try:
        config = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise RouteManagerError(f"cannot read OpenCodex config: {exc}") from exc
    native, provider_allowlists, fallbacks = allowlist()
    providers = config.get("providers")
    if not isinstance(providers, dict):
        raise RouteManagerError("OpenCodex providers object is missing")
    for name, models in provider_allowlists.items():
        provider = providers.get(name)
        if not isinstance(provider, dict):
            raise RouteManagerError(f"allowlisted provider is not configured: {name}")
        provider["selectedModels"] = models
        provider["liveModels"] = False

    allowed_routed = routed_allowset(provider_allowlists)
    custom = config.get("customModels")
    if isinstance(custom, list):
        config["customModels"] = [
            item for item in custom
            if isinstance(item, dict)
            and f"{item.get('provider')}/{item.get('modelId')}" in allowed_routed
        ]

    disabled = {str(item) for item in config.get("disabledModels", []) if "/" in str(item)}
    if catalog_path.is_file():
        try:
            catalog = json.loads(catalog_path.read_text(encoding="utf-8"))
            for item in catalog.get("models", []):
                slug = str(item.get("slug") or "") if isinstance(item, dict) else ""
                if slug and "/" not in slug and slug not in native:
                    disabled.add(slug)
        except (OSError, ValueError):
            pass
    disabled.difference_update(native)
    disabled.difference_update(allowed_routed)
    config["disabledModels"] = sorted(disabled)
    featured = curated_featured(native, provider_allowlists, fallbacks)
    config["subagentModels"] = featured
    atomic_json(config_path, config)
    return {"featured": featured, "allowed_routed": len(allowed_routed),
            "visible_native": native}


def catalog_context(config: dict[str, Any], provider: str, model: str) -> int:
    provider_doc = (config.get("providers") or {}).get(provider) or {}
    windows = provider_doc.get("modelContextWindows") or {}
    value = windows.get(model) if isinstance(windows, dict) else None
    if value is None:
        for item in config.get("customModels", []):
            if (isinstance(item, dict) and item.get("provider") == provider
                    and item.get("modelId") == model):
                value = item.get("contextWindow")
                break
    if value is None:
        caps = config.get("providerContextCaps") or {}
        value = caps.get(provider) if isinstance(caps, dict) else None
    try:
        return int(value) if value is not None else 990000
    except (TypeError, ValueError):
        return 990000


def native_catalog_source() -> list[dict[str, Any]]:
    """Official Codex model records used to restore native picker entries."""
    path = CODEX_HOME / "models_cache.json"
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []
    models = document.get("models")
    if not isinstance(models, list):
        return []
    return [item for item in models if isinstance(item, dict) and item.get("slug")]


def curate_catalog_file() -> dict[str, Any]:
    config = json.loads((OPENCODEX_HOME / "config.json").read_text(encoding="utf-8"))
    path = CODEX_HOME / "opencodex-catalog.json"
    catalog = json.loads(path.read_text(encoding="utf-8"))
    models = catalog.get("models")
    if not isinstance(models, list):
        raise RouteManagerError("Codex model catalog has no models list")
    native, provider_allowlists, _ = allowlist()
    allowed = set(native) | routed_allowset(provider_allowlists)
    kept = [item for item in models if isinstance(item, dict)
            and str(item.get("slug") or "") in allowed]
    by_slug = {str(item.get("slug")): item for item in kept}
    official = {str(item.get("slug")): item for item in native_catalog_source()}
    for slug in native:
        item = official.get(slug)
        if not item:
            continue
        if slug in by_slug:
            index = next(i for i, row in enumerate(kept) if str(row.get("slug")) == slug)
            kept[index] = item
        else:
            kept.append(item)
        by_slug[slug] = item
    template = next((item for item in models if isinstance(item, dict)
                     and "/" in str(item.get("slug") or "")), None)
    if template is None:
        raise RouteManagerError("Codex catalog has no routed model template")
    for provider, model_ids in provider_allowlists.items():
        for model_id in model_ids:
            slug = f"{provider}/{model_id}"
            if slug in by_slug:
                continue
            item = dict(template)
            item.update({
                "slug": slug,
                "display_name": slug,
                "description": "OpenCodex allowlisted routed model",
                "context_window": catalog_context(config, provider, model_id),
                "priority": 20,
            })
            kept.append(item)
            by_slug[slug] = item
    featured = list(config.get("subagentModels") or [])
    rank = {slug: index for index, slug in enumerate(featured)}
    for item in kept:
        slug = str(item.get("slug") or "")
        if slug in rank:
            item["priority"] = rank[slug]
    kept.sort(key=lambda item: (int(item.get("priority", 1000)),
                                str(item.get("slug") or "")))
    catalog["models"] = kept
    atomic_json(path, catalog)
    return {"models": len(kept), "slugs": [str(item.get("slug")) for item in kept]}


def sync_catalog() -> str:
    appdata = Path(os.environ.get("APPDATA", ""))
    package = appdata / "npm" / "node_modules" / "@bitkyc08" / "opencodex"
    bun = package / "node_modules" / "bun" / "bin" / "bun.exe"
    cli = package / "src" / "cli" / "index.ts"
    if not bun.is_file() or not cli.is_file():
        raise RouteManagerError("OpenCodex Bun/CLI installation is unavailable")
    result = subprocess.run([str(bun), str(cli), "sync"], text=True,
                            capture_output=True, timeout=120)
    if result.returncode != 0:
        detail = (result.stderr or result.stdout).strip()
        raise RouteManagerError(f"OpenCodex catalog sync failed: {detail}")
    return (result.stdout + result.stderr).strip()


def curate_and_sync(no_sync: bool) -> dict[str, Any]:
    result = curate_opencodex()
    if not no_sync:
        result["sync"] = sync_catalog()
    result["catalog_file"] = curate_catalog_file()
    return result


def enable_temporary(no_sync: bool) -> dict[str, Any]:
    before = profile_state()
    if MARKER.is_file():
        marker = json.loads(MARKER.read_text(encoding="utf-8"))
        if marker.get("target_profile") != TEMPORARY_PROFILE:
            raise RouteManagerError("a different temporary model override is already active")
        return {"status": "already_active", **profile_state(),
                "catalog": curate_and_sync(no_sync)}
    backup = backup_runtime()
    marker = {
        "schema": "codex-loop-temporary-model-route/v1",
        "status": "switching",
        "previous_profile": before["profile"],
        "target_profile": TEMPORARY_PROFILE,
        "backup": str(backup),
        "started_at": time.time(),
    }
    atomic_json(MARKER, marker)
    try:
        run_profile(TEMPORARY_PROFILE)
        catalog = curate_and_sync(no_sync)
    except Exception:
        try:
            run_profile(before["profile"])
        except Exception as rollback_error:
            marker["status"] = "rollback_failed"
            marker["rollback_error"] = str(rollback_error)
            atomic_json(MARKER, marker)
            raise
        MARKER.unlink(missing_ok=True)
        raise
    marker["status"] = "active"
    marker["activated_at"] = time.time()
    atomic_json(MARKER, marker)
    return {"status": "active", **profile_state(), "backup": str(backup),
            "catalog": catalog}


def restore(no_sync: bool) -> dict[str, Any]:
    if not MARKER.is_file():
        return {"status": "not_active", **profile_state()}
    marker = json.loads(MARKER.read_text(encoding="utf-8"))
    previous = str(marker.get("previous_profile") or "")
    if not previous:
        raise RouteManagerError("temporary route marker has no previous profile")
    backup = backup_runtime()
    run_profile(previous)
    catalog = curate_and_sync(no_sync)
    MARKER.unlink(missing_ok=True)
    return {"status": "restored", **profile_state(), "backup": str(backup),
            "catalog": catalog}


def status() -> dict[str, Any]:
    result: dict[str, Any] = {"temporary": MARKER.is_file(), **profile_state()}
    if MARKER.is_file():
        try:
            marker = json.loads(MARKER.read_text(encoding="utf-8"))
            result["previous_profile"] = marker.get("previous_profile")
            result["temporary_status"] = marker.get("status")
        except ValueError:
            result["temporary_status"] = "corrupt"
    config = json.loads((OPENCODEX_HOME / "config.json").read_text(encoding="utf-8"))
    result["featured"] = config.get("subagentModels", [])
    return result


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="LOOP model route and catalog manager")
    parser.add_argument("command", choices=["enable-grok", "restore", "catalog-sync", "status"])
    parser.add_argument("--no-sync", action="store_true")
    args = parser.parse_args(argv)
    if args.command == "enable-grok":
        result = enable_temporary(args.no_sync)
    elif args.command == "restore":
        result = restore(args.no_sync)
    elif args.command == "catalog-sync":
        backup = backup_runtime()
        result = {"status": "catalog_synced", "backup": str(backup),
                  "catalog": curate_and_sync(args.no_sync)}
    else:
        result = status()
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (OSError, ValueError, RouteManagerError, subprocess.SubprocessError) as exc:
        print(f"model route manager failed: {exc}", file=sys.stderr)
        raise SystemExit(2)

#!/usr/bin/env python3
"""Atomic execution/review model profile switch for Codex LOOP.

Profiles may switch the ordinary execution family and the logical K3 review
family independently.  Roles and pools remain distinct even when a temporary
profile assigns both families to the same physical model.  API credentials
remain owned by OpenCodex.
"""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
import time
import tomllib
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_CODEX_HOME = Path.home() / ".codex"
DEFAULT_WSL_ROOT = Path(r"\\wsl.localhost\Ubuntu\home\codexloop\codex-loop-s-f2")


class ProfileError(RuntimeError):
    pass


def q(value: str) -> str:
    return json.dumps(value, ensure_ascii=False)


def section_span(text: str, section: str | None) -> tuple[int, int]:
    headers = list(re.finditer(r"(?m)^\s*\[([^]\r\n]+)]\s*(?:#.*)?$", text))
    if section is None:
        return 0, headers[0].start() if headers else len(text)
    for idx, match in enumerate(headers):
        if match.group(1).strip() == section:
            return match.end(), headers[idx + 1].start() if idx + 1 < len(headers) else len(text)
    raise ProfileError(f"missing TOML section [{section}]")


def set_toml_key(text: str, section: str | None, key: str, value: str) -> str:
    start, end = section_span(text, section)
    body = text[start:end]
    rx = re.compile(rf'(?m)^(\s*{re.escape(key)}\s*=\s*)[^\r\n]*(\r?\n|$)')
    replacement = rf"\g<1>{q(value)}\g<2>"
    changed, count = rx.subn(replacement, body, count=1)
    if count != 1:
        where = "top level" if section is None else f"[{section}]"
        raise ProfileError(f"missing or duplicate {where}.{key}")
    return text[:start] + changed + text[end:]


def set_inline_reasoning(text: str, section: str, key: str, effort: str) -> str:
    start, end = section_span(text, section)
    body = text[start:end]
    rx = re.compile(rf'(?m)^(\s*{re.escape(key)}\s*=\s*\{{[^\r\n]*?reasoning\s*=\s*")[^"]+("[^\r\n]*\}}\s*(?:#.*)?)(\r?\n|$)')
    changed, count = rx.subn(rf"\g<1>{effort}\g<2>\g<3>", body, count=1)
    if count != 1:
        raise ProfileError(f"missing inline reasoning for [{section}].{key}")
    return text[:start] + changed + text[end:]


def set_yaml_role(text: str, role: str, model: str, effort: str) -> str:
    rx = re.compile(rf"(?ms)^(  {re.escape(role)}:\s*.*?)(?=^  [A-Za-z_][\w-]*:\s*|\Z)")
    match = rx.search(text)
    if not match:
        raise ProfileError(f"missing YAML role {role}")
    block = match.group(1)
    def replace_scalar(match: re.Match[str], value: str) -> str:
        comment = match.group(2)
        return f"{match.group(1)}{value}" + (f" {comment}" if comment else "")

    block, mc = re.subn(r'(?m)^(\s+model:\s*)[^#\r\n]*?(?:\s*(#.*))?$',
                        lambda m: replace_scalar(m, model), block, count=1)
    block, ec = re.subn(
        r'(?m)^(\s+reasoning_effort:\s*)[^#\r\n]*?(?:\s*(#.*))?$',
        lambda m: replace_scalar(m, effort), block, count=1)
    if mc != 1 or ec != 1:
        raise ProfileError(f"incomplete YAML role {role}")
    return text[:match.start(1)] + block + text[match.end(1):]


def load_profiles(root: Path) -> tuple[dict[str, Any], Path]:
    path = root / "config" / "model_profiles.toml"
    try:
        doc = tomllib.loads(path.read_text(encoding="utf-8"))
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise ProfileError(f"profile config unreadable: {path}: {exc}") from exc
    profiles = doc.get("profiles")
    if not isinstance(profiles, dict) or not profiles:
        raise ProfileError("no model profiles configured")
    return doc, path


def profile_values(doc: dict[str, Any], name: str) -> tuple[str, str, str, str]:
    item = (doc.get("profiles") or {}).get(name)
    if not isinstance(item, dict):
        raise ProfileError(f"unknown profile: {name}")
    model, effort = item.get("execution_model"), item.get("execution_reasoning")
    review_model = item.get("review_model", "weiwu-k3/kimi-k3")
    review_effort = item.get("review_reasoning", "max")
    if (not isinstance(model, str) or "/" not in model
            or not isinstance(effort, str)
            or not isinstance(review_model, str) or "/" not in review_model
            or not isinstance(review_effort, str)):
        raise ProfileError(f"invalid profile: {name}")
    return model, effort, review_model, review_effort


def project_updates(root: Path, profile_path: Path, name: str,
                    model: str, effort: str, review_model: str,
                    review_effort: str) -> dict[Path, str]:
    updates: dict[Path, str] = {}

    def edit(rel: str, fn) -> None:
        path = root / rel
        text = path.read_text(encoding="utf-8")
        updates[path] = fn(text)

    profile_text = profile_path.read_text(encoding="utf-8")
    updates[profile_path] = set_toml_key(profile_text, None, "active_profile", name)

    def v2(text: str) -> str:
        text = set_toml_key(text, "models", "v4_model", model)
        text = set_toml_key(text, "models", "v4_reasoning", effort)
        text = set_toml_key(text, "models", "k3_model", review_model)
        return set_toml_key(text, "models", "k3_reasoning", review_effort)
    edit("config/orchestration_policy_v2.toml", v2)

    def agent(text: str) -> str:
        text = set_toml_key(text, None, "model", model)
        return set_toml_key(text, None, "model_reasoning_effort", effort)
    for rel in ("agents/worker.toml", "agents/duty_officer.toml"):
        edit(rel, agent)

    def review_agent(text: str) -> str:
        text = set_toml_key(text, None, "model", review_model)
        return set_toml_key(text, None, "model_reasoning_effort", review_effort)
    for rel in ("agents/reviewer.toml", "agents/verifier.toml",
                "agents/plan_expander.toml"):
        edit(rel, review_agent)

    def defaults(text: str) -> str:
        text = set_toml_key(text, "agents", "default_subagent_model", model)
        return set_toml_key(text, "agents", "default_subagent_reasoning_effort", effort)
    for rel in (".codex/config.toml", "config/config.toml.example"):
        edit(rel, defaults)

    def roles(text: str) -> str:
        for role in ("executor", "scout", "duty_officer"):
            text = set_yaml_role(text, role, model, effort)
        for role in ("reviewer", "verifier", "plan_expander"):
            text = set_yaml_role(text, role, review_model, review_effort)
        return text
    edit("config/roles.yaml", roles)
    return updates


def _ensure_model_catalog(text: str, model: str) -> str:
    doc = json.loads(text)
    models = doc.setdefault("models", [])
    # Codex's catalog schema evolves and contains required fields beyond the
    # obvious model metadata.  Clone a known-good routed entry instead of
    # hand-constructing a partial record that a newer Desktop cannot parse.
    template = next((item for item in models if isinstance(item, dict)
                     and str(item.get("slug", "")).startswith("weiwu/")), None)
    if template is None:
        raise ProfileError("Codex catalog has no routed weiwu template")
    replacement = dict(template)
    replacement.update({"slug": model, "display_name": model,
                        "description": "OpenCodex routed model",
                        "context_window": 990000, "priority": 100})
    for index, item in enumerate(models):
        if isinstance(item, dict) and item.get("slug") == model:
            models[index] = replacement
            break
    else:
        models.append(replacement)
    return json.dumps(doc, ensure_ascii=False, indent=2) + "\n"


def _ensure_opencodex_model(text: str, model: str) -> str:
    doc = json.loads(text)
    provider, model_id = model.split("/", 1)
    provider_doc = (doc.get("providers") or {}).get(provider)
    if not isinstance(provider_doc, dict):
        raise ProfileError(f"OpenCodex provider is not configured: {provider}")
    for key in ("models", "selectedModels"):
        values = provider_doc.setdefault(key, [])
        if model_id not in values:
            values.append(model_id)
    values = doc.setdefault("subagentModels", [])
    if model not in values:
        values.append(model)
    custom = doc.setdefault("customModels", [])
    if not any(isinstance(item, dict) and item.get("provider") == provider
               and item.get("modelId") == model_id for item in custom):
        custom.append({"id": "loop-" + re.sub(r"[^a-z0-9]+", "-", model.lower()).strip("-"),
                       "provider": provider, "modelId": model_id,
                       "displayName": model_id, "contextWindow": 990000,
                       "inputModalities": ["text"], "addedAt": "loop-profile"})
    return json.dumps(doc, ensure_ascii=False, indent=2) + "\n"


def global_updates(codex_home: Path, model: str, effort: str,
                   review_model: str, review_effort: str,
                   canonical_agents: dict[str, str] | None = None) -> dict[Path, str]:
    updates: dict[Path, str] = {}
    config = codex_home / "config.toml"
    if config.is_file():
        text = set_toml_key(config.read_text(encoding="utf-8"), "agents",
                            "default_subagent_model", model)
        updates[config] = set_toml_key(text, "agents",
                                      "default_subagent_reasoning_effort", effort)
    for name in ("worker", "duty_officer"):
        path = codex_home / "agents" / f"{name}.toml"
        if canonical_agents is not None and name in canonical_agents:
            text = canonical_agents[name]
            text = set_toml_key(text, None, "model", model)
            updates[path] = set_toml_key(text, None, "model_reasoning_effort", effort)
        elif path.is_file():
            text = set_toml_key(path.read_text(encoding="utf-8"), None, "model", model)
            updates[path] = set_toml_key(text, None, "model_reasoning_effort", effort)
    for name in ("reviewer", "verifier", "plan_expander"):
        path = codex_home / "agents" / f"{name}.toml"
        if canonical_agents is not None and name in canonical_agents:
            text = canonical_agents[name]
            text = set_toml_key(text, None, "model", review_model)
            updates[path] = set_toml_key(text, None, "model_reasoning_effort",
                                         review_effort)
        elif path.is_file():
            text = set_toml_key(path.read_text(encoding="utf-8"), None,
                                "model", review_model)
            updates[path] = set_toml_key(text, None, "model_reasoning_effort",
                                         review_effort)
    catalog = codex_home / "opencodex-catalog.json"
    if catalog.is_file():
        text = catalog.read_text(encoding="utf-8")
        text = _ensure_model_catalog(text, model)
        updates[catalog] = _ensure_model_catalog(text, review_model)
    ocx = Path.home() / ".opencodex" / "config.json"
    if codex_home.resolve() == DEFAULT_CODEX_HOME.resolve() and ocx.is_file():
        text = _ensure_opencodex_model(ocx.read_text(encoding="utf-8"), model)
        updates[ocx] = _ensure_opencodex_model(text, review_model)
    return updates


def validate_updates(updates: dict[Path, str], model: str, effort: str,
                     review_model: str, review_effort: str,
                     root: Path | None = None) -> None:
    for path, text in updates.items():
        if path.suffix == ".toml":
            try:
                tomllib.loads(text)
            except tomllib.TOMLDecodeError as exc:
                raise ProfileError(f"generated invalid TOML {path}: {exc}") from exc
    project_agents = [p for p in updates if p.as_posix().endswith(("agents/worker.toml", "agents/duty_officer.toml"))]
    for path in project_agents:
        doc = tomllib.loads(updates[path])
        if doc.get("model") != model or doc.get("model_reasoning_effort") != effort:
            raise ProfileError(f"execution pin mismatch after generation: {path}")
    review_agents = [p for p in updates if p.as_posix().endswith(
        ("agents/reviewer.toml", "agents/verifier.toml",
         "agents/plan_expander.toml"))]
    for path in review_agents:
        doc = tomllib.loads(updates[path])
        if (doc.get("model") != review_model
                or doc.get("model_reasoning_effort") != review_effort):
            raise ProfileError(f"review pin mismatch after generation: {path}")
    for path, text in updates.items():
        if path.suffix == ".json":
            json.loads(text)


def atomic_write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.tmp.{os.getpid()}")
    try:
        with tmp.open("w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp, path)
    except Exception:
        tmp.unlink(missing_ok=True)
        raise


def apply_transaction(updates: dict[Path, str]) -> None:
    originals = {path: (path.read_text(encoding="utf-8") if path.is_file() else None)
                 for path in updates}
    written: list[Path] = []
    try:
        for path, text in updates.items():
            atomic_write(path, text)
            written.append(path)
    except Exception:
        errors = []
        for path in reversed(written):
            try:
                original = originals[path]
                if original is None:
                    path.unlink(missing_ok=True)
                else:
                    atomic_write(path, original)
            except Exception as exc:  # best effort; surface every failed restore
                errors.append(f"{path}: {exc}")
        if errors:
            raise ProfileError("switch failed and rollback was incomplete: " + "; ".join(errors))
        raise


def wsl_updates(wsl_root: Path, local_updates: dict[Path, str], root: Path) -> dict[Path, str]:
    if not wsl_root.is_dir():
        return {}
    result: dict[Path, str] = {}
    for source, text in local_updates.items():
        try:
            rel = source.relative_to(root)
        except ValueError:
            continue
        target = wsl_root / rel
        result[target] = text
    return result


def state(root: Path, doc: dict[str, Any]) -> dict[str, Any]:
    active = str(doc.get("active_profile") or "")
    model, effort, review_model, review_effort = profile_values(doc, active)
    return {"profile": active, "execution_model": model,
            "execution_reasoning": effort, "review_model": review_model,
            "review_reasoning": review_effort}


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="atomic LOOP execution-model profile switch")
    ap.add_argument("command", choices=["list", "status", "set"])
    ap.add_argument("profile", nargs="?")
    ap.add_argument("--root", type=Path, default=ROOT)
    ap.add_argument("--codex-home", type=Path, default=DEFAULT_CODEX_HOME)
    ap.add_argument("--wsl-root", type=Path, default=DEFAULT_WSL_ROOT)
    ap.add_argument("--no-global", action="store_true")
    ap.add_argument("--no-wsl", action="store_true")
    ap.add_argument("--json", action="store_true")
    args = ap.parse_args(argv)
    root = args.root.resolve()
    doc, profile_path = load_profiles(root)
    if args.command == "list":
        rows = [{"name": name, **value} for name, value in doc["profiles"].items()]
        print(json.dumps(rows, ensure_ascii=False, indent=2) if args.json else
              "\n".join(
                  f"{r['name']}: execution={r['execution_model']} "
                  f"({r['execution_reasoning']}); review="
                  f"{r.get('review_model', 'weiwu-k3/kimi-k3')} "
                  f"({r.get('review_reasoning', 'max')})" for r in rows))
        return 0
    if args.command == "status":
        value = state(root, doc)
        print(json.dumps(value, ensure_ascii=False) if args.json else
              f"{value['profile']}: execution={value['execution_model']} "
              f"({value['execution_reasoning']}); review="
              f"{value['review_model']} ({value['review_reasoning']})")
        return 0
    if not args.profile:
        ap.error("set requires a profile")
    model, effort, review_model, review_effort = profile_values(doc, args.profile)
    updates = project_updates(root, profile_path, args.profile, model, effort,
                              review_model, review_effort)
    canonical_agents = {
        name: updates[root / "agents" / f"{name}.toml"]
        for name in ("worker", "duty_officer", "reviewer", "verifier",
                     "plan_expander")
    }
    if not args.no_global:
        updates.update(global_updates(args.codex_home.resolve(), model, effort,
                                      review_model, review_effort,
                                      canonical_agents))
    if not args.no_wsl:
        updates.update(wsl_updates(args.wsl_root, updates, root))
        updates.update(global_updates(args.wsl_root.parent / ".codex", model, effort,
                                      review_model, review_effort,
                                      canonical_agents))
    validate_updates(updates, model, effort, review_model, review_effort, root)
    apply_transaction(updates)
    marker = {"schema": "codex-loop-model-profile-state/v1", "ts": time.time(),
              "profile": args.profile, "execution_model": model,
              "execution_reasoning": effort, "review_model": review_model,
              "review_reasoning": review_effort,
              "updated_files": len(updates)}
    atomic_write(root / "data" / "governor" / "model_profile.json",
                 json.dumps(marker, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps(marker, ensure_ascii=False) if args.json else
          f"{args.profile}: {model} ({effort}); updated {len(updates)} files")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (OSError, ProfileError) as exc:
        print(f"model profile switch failed: {exc}", file=sys.stderr)
        raise SystemExit(2)
